import { beforeEach, describe, it } from 'vitest'
import { mockSupabase } from '../../utils/test-utils'
import { appendChangeLog } from './repo'

describe('appendChangeLog', () => {
  beforeEach(() => {
    mockSupabase()
  })

  it('should insert without id field', async () => {
    const { supabase } = mockSupabase()
    const payload = {
      user_id: 'user-123',
      action: 'UPDATE',
      table: 'library',
      record_id: 'lib-456',
      changes: '{}'
    }
    await appendChangeLog(payload)

    expect(supabase.from('changelog').insert).toHaveBeenCalledWith({
      user_id: 'user-123',
      action: 'UPDATE',
      table: 'library',
      record_id: 'lib-456',
      changes: '{}'
    })
  })

  it('should propagate errors', async () => {
    const { supabase } = mockSupabase()
    supabase.from('changelog').insert.mockRejectedValue(new Error('Database error'))
    await expect(appendChangeLog({ user_id: 'user-123', action: 'CREATE' })).rejects.toThrow('Database error')
  })
})

